/*
  холст.js — ВИД ОТ ГЕРОЯ. Мир на холсте 320×200, крупной точкой.

  Чем отличается от соседей: карта.js держит устройство мира — дороги,
  поиск пути, движение героя. Этот файл ничего про мир не решает, он
  только показывает: получает от карты, где герой и по какой дороге
  идёт, и рисует то, что он видит перед собой.

  МИРОВЫХ КООРДИНАТ ЗДЕСЬ НЕТ. Всё считается от экранной строки: где
  середина дороги, какой она ширины, что стоит по сторонам. Отказ от
  мировых координат — решение задания: настоящий поворот камеры с
  обходом вокруг дома запрещён разделом 12, а дешёвый поворот в такой
  рисовке делается переводом двух чисел.

  Шаг первый: небо, земля, дорога, горизонт. Больше ничего.
*/

'use strict';

window.ХОЛСТ = (function () {

const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;

let холст = null, кисть = null, кадр = 0;

/*  Сухость держим отдельно: её спрашивают зелень, дождь, пыль и
    светляки, а протаскивать её через каждый вызов — шум.

    1 — сухой сезон, 0 — дождливый. Зимы нет: она отменена вместе с
    прежним заданием.                                             */
let сухость = 0;

/*  Дома последнего кадра — для попадания пальцем. На холсте нет
    узлов, по которым браузер сам бы понял, куда нажали: попадание
    считаем сами, по тем же местам, где дома нарисованы.          */
let последниеДома = [];

/*  Огни этого кадра. Собираются по ходу рисования: где нарисован
    фонарь — там и светит. Ночью по ним протирается слой тьмы.    */
let огни = [];
const огонь = (x, y, р, сила) => огни.push({ x: x, y: y, р: Math.max(2, р), сила: сила });

/*  Холст под слой тьмы. Заводится один раз: создавать его каждый
    кадр значило бы просить у браузера память шестьдесят раз в
    секунду.                                                       */
let тень = null, кистьТени = null;

/* ═══ 1 · КРАСКИ ═══════════════════════════════════════════════════ */

const мешать = (а, б, доля) =>
  а.map((знач, и) => Math.round(знач + (б[и] - знач) * доля));

const цвет = (краска) => 'rgb(' + краска[0] + ',' + краска[1] + ',' + краска[2] + ')';

/* ═══ 1а · ВРЕМЯ ═══════════════════════════════════════════════════
   Время суток и года берутся у человека в браузере. Наружу ничего не
   уходит: ни часов, ни дня, ни того, что он вообще заходил.

   Человек, зашедший через полгода, видит другой мир. Это повод
   вернуться, и стоит он одной строки.                              */

/*  Проверочная подмена. Ею я показываю оба края владельцу, не
    дожидаясь настоящего полудня и настоящего лета. В продукте не
    зовётся ниоткуда: время берётся у часов.                       */
let напоказ = null;

function время() {
  if (напоказ) return напоказ;
  const в = НАСТРОЙКИ.холст.время;
  const сейчас = new Date();

  /*  Насколько светло. Не по номеру часа, а по косинусу от полудня:
      рассвет и закат приходят плавно, а не ступенькой.           */
  const часы = сейчас.getHours() + сейчас.getMinutes() / в.минутВЧасе;
  const суток = (Math.cos((часы - в.полденьЧас) / в.часовВСутках * Math.PI * 2) + 1) / 2;

  /*  Сезон — по дню года, оттого переход плавный, а не переключатель. */
  const началоГода = new Date(сейчас.getFullYear(), 0, 0);
  const день = Math.floor((сейчас - началоГода) / в.мсВСутках);
  const года = (Math.cos((день - в.серединаСухого) / в.днейВГоду * Math.PI * 2) + 1) / 2;

  return { суток: суток, года: года };
}

/*  Палитра на сейчас: ночь мешается с днём, дождливое с сухим.  */
function палитра(т) {
  const к = НАСТРОЙКИ.холст.краски;
  const п = {};
  for (const имя in к.ночь) п[имя] = мешать(к.ночь[имя], к.закат[имя], т.суток);
  for (const имя in к.дождливый) п[имя] = мешать(к.дождливый[имя], к.сухой[имя], т.года);
  for (const имя in к.дом) п[имя] = мешать(к.дом[имя], к.домДень[имя], т.суток);
  return п;
}

/* ═══ 2 · ПЕРСПЕКТИВА ══════════════════════════════════════════════
   Глубина: 0 у горизонта, 1 у нижнего края. Всё остальное — от неё. */

function глубина(строка) {
  const х = НАСТРОЙКИ.холст;
  const от = х.горизонт + х.отступГоризонта;
  return Math.max(0, Math.min(1, (строка - от) / (х.высота - от)));
}

const ширинаДороги = (строка) => {
  const х = НАСТРОЙКИ.холст;
  return х.дорогаУГоризонта + Math.pow(глубина(строка), х.законСужения) * х.дорогаРазмах;
};

/*  На какой строке экрана стоит основание предмета этой глубины.
    Тот же закон, по которому ставятся дома, — иначе полосы дымки
    легли бы не там, где стоят дома, и рассекли бы их пополам.    */
function строкаПоДоле(доля) {
  const х = НАСТРОЙКИ.холст, н = х.дом;
  return х.горизонт + н.отступГоризонта +
         (х.высота - х.горизонт - н.отступНиза) * Math.pow(1 - доля, н.законРоста);
}

/*  СЕРЕДИНА ДОРОГИ. Изгиб идёт от кривизны кольца, на котором стоит
    герой: чем кольцо теснее, тем сильнее ведёт. На луче и тропке
    изгиб равен нулю, и дорога идёт прямой.

    Вбок от поворота камеры здесь ничего не сдвигается, и это
    осознанно. Проба показала: сдвинуть даль на угол поворота — тот
    самый рывок и есть. Разбор в журнале.                          */
function серединаДороги(строка, изгиб) {
  const х = НАСТРОЙКИ.холст;
  const г = глубина(строка);
  return х.ширина / 2 +
    Math.sin(г * х.изгибЧастота + х.изгибСдвиг) * х.изгибРазмах * г * изгиб +
    Math.sin(г * х.изгибРябьЧастота) * х.изгибРябь * г * изгиб;
}

/* ═══ 3 · РИСОВАНИЕ ════════════════════════════════════════════════ */

function точки(x, y, ш, в, краска) {
  кисть.fillStyle = краска;
  кисть.fillRect(Math.round(x), Math.round(y), Math.max(1, Math.round(ш)),
                 Math.max(1, Math.round(в)));
}

function небо(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = 0; y < х.горизонт; y++) {
    const доля = Math.pow(y / х.горизонт, х.небоСтепень);
    точки(0, y, х.ширина, 1, цвет(мешать(п.небоВерх, п.небоНиз, доля)));
  }
  /* зарево у самого горизонта: небо у земли всегда светлее */
  for (let y = х.горизонт - х.заревоВысота; y < х.горизонт; y++) {
    кисть.globalAlpha = ((y - (х.горизонт - х.заревоВысота)) / х.заревоВысота) * х.заревоСила;
    точки(0, y, х.ширина, 1, цвет(п.зарево));
    кисть.globalAlpha = 1;
  }
}

/*  ЛУНА. Крупная, с кратерами и мягким гало. Ночью видна, к
    рассвету тает — оттого её сила берётся из темноты суток.      */
function луна(п, темнота) {
  const л = НАСТРОЙКИ.холст.луна, х = НАСТРОЙКИ.холст;
  if (темнота <= 0) return;
  const цx = Math.round(х.ширина * л.поШирине);
  const цy = Math.round(х.горизонт * л.поВысоте);

  кисть.globalAlpha = л.гало * темнота;
  for (let р = л.радиус * л.галоРазмах; р > л.радиус; р -= л.галоШаг) {
    круг(цx, цy, р, цвет(л.галоКраска));
  }
  кисть.globalAlpha = темнота;
  круг(цx, цy, л.радиус, цвет(л.краска));
  круг(цx - л.бликСмещение, цy - л.бликСмещение, л.радиус - л.блик, цвет(л.бликКраска));
  л.кратеры.forEach((к) => круг(цx + к[0], цy + к[1], к[2], цвет(л.кратерКраска)));
  кисть.globalAlpha = 1;
  огонь(цx, цy, л.радиус * л.светЗапас, л.светДиск * темнота);
  огонь(цx, цy, л.радиус * л.светГалоРазмах, л.светГало * темнота);
  return цx;
}

function круг(цx, цy, р, краска) {
  кисть.fillStyle = краска;
  for (let dy = -р; dy <= р; dy++) {
    const ш = Math.round(Math.sqrt(Math.max(0, р * р - dy * dy)));
    if (ш > 0) кисть.fillRect(Math.round(цx - ш), Math.round(цy + dy), ш * 2, 1);
  }
}

function земля(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт; y < х.высота; y++) {
    точки(0, y, х.ширина, 1, цвет(мешать(п.землД, п.землБ, глубина(y))));
  }
}

/*  Дорога. Кромки протоптаны светлее, по середине две колеи темнее —
    это то, что отличает тракт от полосы краски.                   */
function дорога(п, изгиб) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт + х.отступГоризонта; y < х.высота; y++) {
    const ц = серединаДороги(y, изгиб), ш = ширинаДороги(y), г = глубина(y);
    const полотно = мешать(п.дорога, мешать(п.дорога, п.землБ, х.дорогаДаль), г);
    точки(ц - ш / 2, y, ш, 1, цвет(полотно));

    const кромка = цвет(мешать(п.дорога, п.землБ, х.кромкаСвет));
    точки(ц - ш / 2, y, ш * х.кромкаДоля, 1, кромка);
    точки(ц + ш / 2 - ш * х.кромкаДоля, y, ш * х.кромкаДоля, 1, кромка);

    кисть.globalAlpha = х.колеяПрозрачность;
    const колея = цвет(мешать(п.дорога, [0, 0, 0], х.колеяТень));
    точки(ц - ш * х.колеяСлева, y, ш * х.колеяДоля, 1, колея);
    точки(ц + ш * х.колеяСправа, y, ш * х.колеяДоля, 1, колея);
    кисть.globalAlpha = 1;
  }
}

/* ═══ 4 · ДОМА ═════════════════════════════════════════════════════
   Японские, с широкими крышами. Ярус устроен сверху вниз: крыша
   ступенями с приподнятыми концами, мох на левом скате, конёк
   светлее, корпус с балкой и стойками, три бумажных окна.

   Верхний ярус уже нижнего. Ярусов даёт кольцо, а не случай, — это
   решает карта, здесь мы только рисуем.                            */

/*  Устойчивая случайность: одно и то же число для одного и того же
    дома. Обычный бросок дал бы дрожь на каждом кадре.             */
const порознь = (и, ширина) => {
  const с = НАСТРОЙКИ.холст.случайность;
  return ((и * с.множитель + Math.round(ширина) * с.шаг) % с.делитель) / с.делитель;
};

function крышаЯруса(п, x, верх, шя, св, вк) {
  const я = НАСТРОЙКИ.холст.дом.ярус;
  for (let р = 0; р < вк; р++) {
    const доля = р / вк;
    const ш2 = Math.round((шя + св * 2) * (1 - доля * я.сужениеКрыши));
    const подъём = Math.round(Math.pow(1 - доля, я.законПодъёма) * шя * я.подъёмКонцов);
    точки(x - ш2 / 2, верх - р - 1, ш2, 1, цвет(п.крыша));
    /*  МОХ ЛОЖИТСЯ НА САМ СКАТ, строку за строкой, а не полосой
        поверх узкой верхушки: полоса торчала бы в стороне от крыши
        и читалась бы как оборванная черта в воздухе.

        Слева — потому что свет слева сверху, это правило мира.
        Проплешины — синусом по скату: сплошная полоса читается как
        краска, а не как мох.                                     */
    const мшисто = (Math.sin(р * я.мохПятна) + 1) / 2;
    кисть.globalAlpha = я.мохСила * мшисто;
    точки(x - ш2 / 2, верх - р - 1, Math.round(ш2 * я.мохДоля), 1, цвет(п.мох));
    кисть.globalAlpha = 1;
    if (р < 2) {   // концы приподняты только у самого низа крыши
      точки(x - ш2 / 2 - подъём, верх - р - 1 - Math.round(подъём / 2), подъём + 1, 1, цвет(п.крыша));
      точки(x + ш2 / 2, верх - р - 1 - Math.round(подъём / 2), подъём + 1, 1, цвет(п.крыша));
    }
  }
  /* конёк светлее крыши */
  точки(x - Math.round(шя * я.конёкШирина / 2), верх - вк - 1,
        Math.round(шя * я.конёкШирина), 2,
        цвет(мешать(п.крыша, п.крышаС, я.конёкСвет)));
}

function окнаЯруса(п, дом, x, верх, шя, вя, номерЯруса) {
  const о = НАСТРОЙКИ.холст.дом.окно;
  const ош = Math.max(2, Math.round(шя * о.ширина));
  const ов = Math.max(2, Math.round(вя * о.высота));
  for (let и = 0; и < о.сколько; и++) {
    const ох = Math.round(x - шя / 2 + шя * о.отступ + и * шя * о.шаг);
    const оу = Math.round(верх + вя * о.сверху);
    if (дом.открыт) {
      огонь(ох + ош / 2, оу + ов / 2, шя * о.светРадиус, о.светСила);
      /*  Окна мерцают вразнобой: у каждого свой сдвиг по кадру,
          иначе весь порядок домов моргает разом.                */
      const н = НАСТРОЙКИ.холст.дом;
      const дрожь = (Math.sin((кадр + и * н.сдвигОкна + номерЯруса * н.сдвигЯруса) /
                              о.мерцаниеШаг) + 1) / 2;
      кисть.globalAlpha = о.свет + дрожь * о.мерцание;
      точки(ох, оу, ош, ов, цвет(п.теплоС));
      кисть.globalAlpha = о.отсвет;
      const поле = НАСТРОЙКИ.холст.дом.отсветПоле;
      точки(ох - поле, оу - поле, ош + поле * 2, ов + поле * 2, цвет(п.тепло));
      кисть.globalAlpha = 1;
    } else {
      точки(ох, оу, ош, ов, цвет(мешать(п.деревоТ, [0, 0, 0], о.темнота)));
    }
    if (шя > о.переплётОт) {   // переплёт различим только вблизи
      точки(ох, оу + Math.round(ов / 2), ош, 1, цвет(п.деревоТ));
      точки(ох + Math.round(ош / 2), оу, 1, ов, цвет(п.деревоТ));
    }
  }
}

function дом(п, д) {
  const н = НАСТРОЙКИ.холст.дом;
  const я = н.ярус, x = д.x, ш = д.ш;

  /* тень под домом: без неё дом висит над землёй */
  кисть.globalAlpha = н.тень.сила;
  точки(x - ш * н.тень.доля / 2, д.y - 1, ш * н.тень.доля, н.тень.высота,
        цвет(п.тень));
  кисть.globalAlpha = 1;

  let низ = д.y;
  д.верх = д.y;            // запомним, докуда дом достал: нужно для нажатия
  for (let номер = 0; номер < д.ярусов; номер++) {
    const шя = Math.round(ш * Math.pow(я.сжатие, номер));
    const вя = Math.round(шя * я.высота);
    const св = Math.round(шя * я.свес), вк = Math.round(шя * я.крыша);
    const верх = низ - вя;

    точки(x - шя / 2, верх, шя, вя, цвет(п.дерево));
    /* левая кромка светлее: свет слева сверху */
    точки(x - шя / 2, верх, Math.max(1, шя * я.кромкаСлева), вя,
          цвет(мешать(п.дерево, п.крышаС, я.кромкаСвет)));
    /* холодная подсветка снизу, против тёплого из окон */
    кисть.globalAlpha = н.подсветкаСнизу.сила;
    точки(x - шя / 2, верх + вя * н.подсветкаСнизу.от, шя, вя * н.подсветкаСнизу.доля,
          цвет(п.подсветка));
    кисть.globalAlpha = 1;
    /* правая грань темнее */
    точки(x + шя / 2 - Math.max(1, шя * я.граньСправа), верх,
          Math.max(1, шя * я.граньСправа), вя, цвет(п.деревоТ));
    /* балка поперёк и стойки */
    точки(x - шя / 2, низ - Math.round(вя * я.балкаНа), шя,
          Math.max(1, шя * я.балкаТолщина), цвет(п.деревоТ));
    for (let и = 1; и < я.стоек; и++) {
      точки(x - шя / 2 + шя * и / я.стоек, верх,
            Math.max(1, шя * я.стойкаТолщина), вя, цвет(п.деревоТ));
    }

    окнаЯруса(п, д, x, верх, шя, вя, номер);
    крышаЯруса(п, x, верх, шя, св, вк);
    низ = верх - вк - 1;
    д.верх = низ;
  }
  зеленьСКрыши(п, д);
}

/*  Зелень, свисающая с крыши. Летом гуще, зимой её нет вовсе.   */
function зеленьСКрыши(п, д) {
  const з = НАСТРОЙКИ.холст.дом.зелень, я = НАСТРОЙКИ.холст.дом.ярус;
  if (д.ш <= з.мельче || сухость <= з.летомОт) return;
  const сколько = Math.round(з.основа + д.ш / з.наПлеть);
  const длинаДоли = Math.min(1, (сухость - з.началоРоста) / з.наборРоста);
  for (let и = 0; и < сколько; и++) {
    const зx = Math.round(д.x - д.ш * з.размах / 2 + порознь(и, д.ш) * д.ш * з.размах);
    const длина = Math.round((з.короткая + порознь(и + з.сдвиг, д.ш) * з.длинная) * длинаДоли);
    for (let d = 0; d < длина; d++) {
      точки(зx + Math.round(Math.sin(d * з.виток + и) * з.отклонение),
            д.y - д.ш * я.высота - д.ш * я.крыша + d, 1, 1,
            цвет(мешать(п.листва, п.хвоя, (d % з.пестрота) / з.пестротаСила)));
    }
  }
}

/*  ТРОПИНКА от кромки дороги к крыльцу. Дугой, с расширением у
    дома: дом не примыкает к тракту вплотную.                     */
function тропинка(п, д, изгиб) {
  const т = НАСТРОЙКИ.холст.дом.тропа;
  const от = серединаДороги(д.y, изгиб) + д.сторона * ширинаДороги(д.y) / 2;
  const до = д.x - д.сторона * д.ш * т.уКрыльца;
  const шагов = Math.max(т.шаговНеМенее, Math.abs(до - от));
  for (let с = 0; с <= шагов; с++) {
    const доля = с / шагов;
    const x = от + (до - от) * доля;
    const y = д.y - Math.sin(доля * Math.PI) * д.ш * т.дуга - доля * т.подъём;
    точки(x, y, Math.max(1, д.ш * т.ширина * доля), 1, цвет(п.тропа));
  }
}

/*  Фонарный столб у начала тропинки. У закрытой лавки погашен, но
    виден: занятость читается видом.                              */
function столб(п, д) {
  const с = НАСТРОЙКИ.холст.дом.столб;
  if (д.ш <= с.мельче) return;
  const сx = Math.round(д.x - д.сторона * д.ш * с.отДома);
  const сy = Math.round(д.y + д.ш * с.наЗемле);
  const вс = Math.round(д.ш * с.высота);
  const гр = Math.max(с.навершиеНеМенее, Math.round(д.ш * с.навершие));
  const верхНавершия = сy - вс - Math.round(гр * с.доляНавершия);

  точки(сx, сy - вс, Math.max(1, Math.round(д.ш * с.толщина)), вс, цвет(п.деревоТ));
  точки(сx - Math.round(гр / 2) + 1, верхНавершия, гр, Math.round(гр * с.доляНавершия),
        д.открыт ? цвет(п.теплоС) : цвет(мешать(п.деревоТ, п.землД, с.погашен)));
  точки(сx - Math.round(гр / 2), верхНавершия - с.крышечка, гр + 1, с.крышечка,
        цвет(п.крыша));

  if (д.открыт) {   // тёплое гало и пятно на земле
    огонь(сx, верхНавершия + гр / 2, д.ш * с.светРадиус, с.светСила);
    кисть.globalAlpha = с.гало;
    точки(сx - гр, сy - вс - гр, гр * 2 + 2, гр * 2 + 2, цвет(п.тепло));
    кисть.globalAlpha = с.пятно;
    точки(сx - гр * с.пятноШирина / 2, сy - 1, гр * с.пятноШирина, с.пятноВысота,
          цвет(п.тепло));
    кисть.globalAlpha = 1;
  }
}

/*  Бумажные фонарики под свесом крыши. Чем ближе дом, тем больше. */
function фонарики(п, д) {
  const ф = НАСТРОЙКИ.холст.дом.фонарик;
  if (д.ш <= ф.мельче) return;
  const я = НАСТРОЙКИ.холст.дом.ярус;
  const фy = Math.round(д.y - д.ш * я.высота - д.ш * я.крыша) + 2;
  const сколько = д.ш > ф.многоОт ? ф.много : (д.ш > ф.среднеОт ? ф.средне : ф.мало);
  for (let и = 0; и < сколько; и++) {
    const фx = Math.round(д.x - д.ш * ф.отступ +
                          и * (д.ш * ф.размах / (сколько - 1 || 1)));
    const р = Math.max(2, Math.round(д.ш * ф.размер));
    точки(фx, фy - ф.подвес, 1, ф.подвес, цвет(п.деревоТ));
    if (д.открыт) {
      огонь(фx, фy + р / 2, д.ш * ф.светРадиус, ф.светСила);
      const дрожь = (Math.sin((кадр + и * ф.сдвиг) / ф.мерцаниеШаг) + 1) / 2;
      кисть.globalAlpha = ф.свет + дрожь * ф.мерцание;
      точки(фx - Math.round(р / 2), фy, р, р + 1, цвет(п.теплоС));
      точки(фx - Math.round(р / 2), фy + Math.round(р / 2), р, 1, цвет(п.тепло));
      кисть.globalAlpha = ф.гало;
      точки(фx - р, фy - Math.round(р / 2), р * 2, р * 2, цвет(п.тепло));
      кисть.globalAlpha = 1;
    } else {
      точки(фx - Math.round(р / 2), фy, р, р + 1,
            цвет(мешать(п.деревоТ, п.землД, ф.погашен)));
    }
  }
}

/* ═══ 5 · ГЕРОЙ ════════════════════════════════════════════════════
   По миру ходит сам герой — картинка из библиотеки с вырезанным
   фоном. Её нет — рисуем фигурку кодом: мир открывается всегда.    */

/*  Картинки грузятся один раз и запоминаются. Пути пробуются по
    очереди: точная фигура, потом ближайшая. Ни одна не загрузилась —
    остаётся `null`, и рисуется фигурка.                           */
const запомненные = {};

function картинка(пути) {
  if (!пути || !пути.length) return null;
  const ключ = пути.join('|');
  if (!(ключ in запомненные)) {
    запомненные[ключ] = null;
    (function пробовать(номер) {
      if (номер >= пути.length) return;
      const кадрик = new Image();
      кадрик.onload = () => { запомненные[ключ] = кадрик; };
      кадрик.onerror = () => пробовать(номер + 1);
      кадрик.src = пути[номер];
    })(0);
  }
  return запомненные[ключ];
}

/*  Запасная фигурка. Плащ и есть вся фигура: на этом размере
    читается силуэт, а не руки и ноги.                            */
function фигурка(цвета, x, низ, рост, качание) {
  const р = НАСТРОЙКИ.холст.герой.рисованный;
  const плечи = Math.round(рост * р.плечи);
  const ноги = Math.round(рост * р.ноги);

  точки(x - р.ногаОтступ, низ - ноги, р.ногаШирина, ноги, цвета.плащ);
  точки(x + р.ногаОтступ - р.ногаШирина, низ - ноги, р.ногаШирина, ноги, цвета.плащ);

  const вп = Math.round(рост * р.плащВысота), верхНог = низ - ноги;
  for (let строка = 0; строка < вп; строка++) {
    const доля = строка / вп;
    const ш = Math.round(плечи * 2 * (р.плащУзко + доля * р.плащРаструб));
    точки(x - ш / 2, верхНог - вп + строка + качание, ш, 1, цвета.плащ);
    кисть.globalAlpha = р.светСила;   // свет слева сверху
    точки(x - ш / 2, верхНог - вп + строка + качание, Math.round(ш * р.светДоля), 1,
          цвет(НАСТРОЙКИ.холст.краски.блик));
    кисть.globalAlpha = 1;
  }

  const гy = верхНог - вп + качание;
  точки(x - плечи, гy - 2, плечи * 2, р.плечиВысота, цвета.плащ);
  точки(x - Math.round(плечи * р.головаШирина / 2), гy - Math.round(рост * р.головаВысота),
        Math.round(плечи * р.головаШирина), Math.round(рост * р.головаВысота), цвета.кожа);
  точки(x - Math.round(плечи * р.волосыШирина / 2), гy - Math.round(рост * р.волосыВысота),
        Math.round(плечи * р.волосыШирина), р.волосыТолщина, цвета.волосы);
}

function герой(п, вид) {
  const х = НАСТРОЙКИ.холст, г = х.герой;
  const низ = х.высота - г.отНиза;
  const x = Math.round(серединаДороги(низ, вид ? вид.изгиб : 0));

  /*  Покачивание берётся из пройденного пути, а не из номера кадра:
      стоит на месте — не качается.                               */
  const пройдено = вид ? вид.пройдено || 0 : 0;
  const качание = Math.round(Math.sin(пройдено / г.качаниеДелитель) * г.качаниеРазмах);

  /*  Тень под ногами: без неё герой висит над землёй. Эллипсом, а не
      полосой: под ногами лежит пятно, а не доска.                 */
  эллипс(x, низ, г.рост * г.тень.доля / 2, г.тень.высота, п.тень, г.тень.сила);

  огонь(x, низ - г.рост * г.свет.поРосту, г.свет.радиус, г.свет.сила);

  const кадрик = картинка(вид && вид.фигуры);
  if (кадрик) {
    const ширина = Math.round(г.рост * кадрик.naturalWidth / кадрик.naturalHeight);
    кисть.imageSmoothingEnabled = false;   // крупная точка, без сглаживания
    кисть.drawImage(кадрик, Math.round(x - ширина / 2),
                    Math.round(низ - г.рост + качание), ширина, г.рост);
  } else {
    фигурка((вид && вид.цвета) || {}, x, низ + качание, г.рост, 0);
  }
}

/* ═══ 6 · ДЕРЕВЬЯ ══════════════════════════════════════════════════
   Ели и лиственные, вперемешку с домами по глубине: дерево может
   закрыть дом, как в жизни.                                        */

/* ═══ 4в · РАСТЕНИЯ ════════════════════════════════════════════════
   Джунгли доисторические. Силуэты с образца-03: гигантские стволы,
   уходящие за верх кадра, древовидные папоротники, саговники, хвощи,
   подлесок и свисающие лианы.

   Всё рисуется кодом. Общего у них два приёма: СТВОЛ со светлой
   левой кромкой (свет слева сверху — правило мира) и ВАЙЯ — дуга с
   перьями по обе стороны. Из них и собрано остальное.             */

function ствол(п, x, низ, ш, в, кромка, граньТ) {
  точки(x - ш / 2, низ - в, ш, в, цвет(п.ствол));
  точки(x - ш / 2, низ - в, Math.max(1, ш * кромка), в,
        цвет(мешать(п.ствол, п.хвояС, кромка)));
  точки(x + ш / 2 - Math.max(1, ш * граньТ), низ - в,
        Math.max(1, ш * граньТ), в, цвет(мешать(п.ствол, п.тень, граньТ * 2)));
}

/*  ВАЙЯ. Дуга из точки (x, y) под углом `угол`, длиной `длина`,
    клонящаяся вниз к концу. По обе стороны — перья, к концу короче.

    Ею рисуются и папоротник, и саговник, и подлесок: разница только
    в числах, а не в отдельном коде на каждое растение.            */
function вайя(п, x, y, угол, длина, н, тёмная) {
  const шагов = Math.max(НАСТРОЙКИ.холст.дерево.шаговНеМенее, Math.round(длина));
  const край = мешать(п.листва, тёмная ? п.хвоя : п.хвояС, н.шагПера);
  for (let с = 0; с <= шагов; с++) {
    const t = с / шагов;
    const вx = x + Math.cos(угол) * длина * t;
    const вy = y + Math.sin(угол) * длина * t + н.провис * длина * t * t;
    точки(вx, вy, 1, 1, цвет(п.хвоя));
    /*  Перья к концу короче: у вайи кончик тоньше черенка.      */
    const перо = длина * н.пера * (1 - t);
    if (перо < 1) continue;
    for (let з = 1; з <= н.перьев; з++) {
      const доля = з / н.перьев;
      const пx = Math.round(вx - Math.sin(угол) * перо * доля);
      const пy = Math.round(вy + Math.cos(угол) * перо * доля);
      точки(пx, пy, 1, 1, цвет(край));
      точки(Math.round(вx + Math.sin(угол) * перо * доля),
            Math.round(вy - Math.cos(угол) * перо * доля), 1, 1, цвет(п.листва));
    }
  }
}

/*  Венец вай над стволом: веер, раскрытый вверх и в стороны.     */
function венец(п, x, y, в, н, ключ) {
  const середина = НАСТРОЙКИ.холст.дерево.серединаВеера;
  for (let и = 0; и < н.вай; и++) {
    const доля = н.вай > 1 ? и / (н.вай - 1) : середина;
    const угол = -Math.PI / 2 - н.разлёт / 2 + н.разлёт * доля;
    const длина = в * (н.длина + порознь(и + ключ, в) * н.длинаРазбег);
    вайя(п, x, y, угол, длина, н, и % 2 === 0);
  }
}

/*  ГИГАНТ. Ствол уходит за верх кадра — оттого и гигант. У основания
    досковидные корни, по стволу мох, с высоты свисают лианы.

    Верх не рисуем вовсе: кроны у него нет в кадре, она выше.     */
function гигант(п, д) {
  const г = НАСТРОЙКИ.холст.дерево.гигант;
  /*  Гигант всегда уходит за верх кадра: у него и кроны в кадре нет,
      она выше. Оборвись он в воздухе — вышла бы не пальма, а столб. */
  const в = Math.max(д.в * г.ростВРаз, д.y + г.заВерх);
  const x = д.x, низ = д.y;
  const ш = Math.max(2, Math.round(д.в * г.ростВРаз * г.толщина *
                     (1 - порознь(Math.round(x), д.в) * г.толщинаРазбег)));

  /* досковидные корни: треугольниками в стороны от комля */
  for (let к = 0; к < г.корней; к++) {
    const сторона = к === 0 ? 0 : (к % 2 === 0 ? 1 : -1);
    const кв = Math.round(ш * г.кореньВысота);
    const кш = Math.round(ш * г.кореньШирина);
    for (let р = 0; р < кв; р++) {
      const доля = р / кв;
      const ширь = Math.round(кш * (1 - доля));
      точки(x + сторона * ш / 2 - ширь / 2, низ - р, ширь, 1,
            цвет(мешать(п.ствол, п.тень, г.граньТ)));
    }
  }

  ствол(п, x, низ, ш, в, г.кромка, г.граньТ);

  /* кора: длинные вертикальные борозды */
  for (let к = 0; к < г.коры; к++) {
    const кx = Math.round(x - ш / 2 + порознь(к, ш) * ш);
    кисть.globalAlpha = г.кораСила;
    точки(кx, низ - в, 1, в, цвет(п.тень));
    кисть.globalAlpha = 1;
  }

  /* мох по левой стороне, пятнами */
  for (let y = Math.round(в * г.мхаОт); y < в * г.мхаДо; y++) {
    const пятно = (Math.sin(y * г.мохПятна) + 1) / 2;
    if (пятно < г.мохПятна) continue;
    кисть.globalAlpha = г.мохСила * пятно;
    точки(x - ш / 2, низ - y, Math.max(1, ш * г.мохШирина), 1, цвет(п.мох));
    кисть.globalAlpha = 1;
  }

  /* лианы с высоты: нити с листочками, покачиваются */
  for (let л = 0; л < г.лиан; л++) {
    const лx = Math.round(x - ш / 2 + порознь(л + г.лиан, ш) * ш);
    const верх = низ - в * (г.лианаОт + порознь(л, ш) * г.лианаРазбег);
    const длина = Math.round(в * г.лианаДлина *
                             (1 - порознь(л + г.коры, ш) * г.лианаКороче));
    for (let d = 0; d < длина; d++) {
      const сдвиг = Math.round(Math.sin(d * г.лианаВиток + л + кадр / НАСТРОЙКИ.холст.времяКадров) *
                               г.лианаОтклон);
      точки(лx + сдвиг, верх + d, 1, 1,
            цвет(d % г.лианаЛист === 0 ? п.листва : п.хвоя));
    }
  }
}

function папоротник(п, д) {
  const н = НАСТРОЙКИ.холст.дерево.папоротник, в = д.в;
  const вс = Math.round(в * н.стволВысота);
  ствол(п, д.x, д.y, Math.max(1, Math.round(в * н.стволТолщина)), вс, н.стволТолщина, н.стволТолщина);
  венец(п, д.x, д.y - вс, в, н, н.вай);
}

function саговник(п, д) {
  const н = НАСТРОЙКИ.холст.дерево.саговник, в = д.в;
  const вс = Math.round(в * н.стволВысота);
  ствол(п, д.x, д.y, Math.max(2, Math.round(в * н.стволТолщина)), вс, н.стволТолщина, н.стволТолщина);
  венец(п, д.x, д.y - вс, в, н, н.вай);
}

/*  ХВОЩ. Тонкие стебли с мутовками иголок — того же устройства, что
    и сотни миллионов лет назад.                                   */
function хвощ(п, д) {
  const н = НАСТРОЙКИ.холст.дерево.хвощ, в = д.в;
  for (let с = 0; с < н.стеблей; с++) {
    const своё = порознь(с, в);
    const сx = Math.round(д.x + (своё * 2 - 1) * в * н.разброс);
    const высота = Math.round(в * (н.высота + своё * н.высотаРазбег));
    const наклон = (своё * 2 - 1) * н.наклон;
    for (let y = 0; y < высота; y++) {
      const т = y / высота;
      точки(сx + наклон * y, д.y - y, Math.max(1, в * н.толщина), 1, цвет(п.хвоя));
      if (y % Math.max(2, Math.round(высота / н.мутовок))) continue;
      const игла = в * н.игла * (1 - т);
      точки(сx + наклон * y - игла, д.y - y - игла / 2, игла, 1, цвет(п.листва));
      точки(сx + наклон * y, д.y - y - игла / 2, игла, 1, цвет(п.хвояС));
    }
  }
}

/*  ПОДЛЕСОК. Розетка вай прямо из земли, без ствола.             */
function подлесок(п, д) {
  const н = НАСТРОЙКИ.холст.дерево.подлесок, в = д.в * н.приземистость;
  const середина = НАСТРОЙКИ.холст.дерево.серединаВеера;
  for (let и = 0; и < н.вай; и++) {
    const доля = н.вай > 1 ? и / (н.вай - 1) : середина;
    const угол = -Math.PI / 2 - н.разлёт / 2 + н.разлёт * доля;
    const длина = в * (н.длина + порознь(и, в) * н.длинаРазбег);
    вайя(п, д.x, д.y, угол, длина, н, и % 2 === 0);
  }
}

const РАСТЕНИЯ = { гигант: гигант, папоротник: папоротник, саговник: саговник,
                   хвощ: хвощ, подлесок: подлесок };

function дерево(п, д) {
  const т = НАСТРОЙКИ.холст.дерево;
  /*  Тень под комлем: без неё растение висит над землёй.        */
  эллипс(д.x, д.y, д.в * т.тень.доля / 2, т.тень.высота, п.тень, т.тень.сила);
  const рисовать = РАСТЕНИЯ[д.порода];
  if (рисовать) рисовать(п, д);
}

/*  Какая порода у этого места. Шаг по индексу иной, чем у глубины:
    у нашей устойчивой случайности соседние ключи дают один и тот же
    ряд со сдвигом, и порода легла бы ровно по глубине — дальше одно,
    ближе другое.                                                  */
function порода(и, т) {
  let бросок = порознь(и * т.шагПороды, т.сколько);
  let последняя = null;
  for (const имя in т.доли) {
    последняя = имя;
    бросок -= т.доли[имя];
    if (бросок <= 0) return имя;
  }
  return последняя;          // доли не сошлись в единицу — берём последнюю
}

/*  Деревья расставляются устойчиво: одно и то же дерево на одном и
    том же месте от кадра к кадру. Иначе лес дрожал бы.

    Но лес ЕДЕТ НАВСТРЕЧУ: доля каждого дерева уменьшается на
    пройденный путь. Стоишь — лес стоит, идёшь — лес идёт мимо. Без
    этого мир был неподвижной картинкой: шагаешь, а деревья на
    прежних местах.                                                */
function поставитьДеревья(изгиб, бег) {
  const х = НАСТРОЙКИ.холст, т = х.дерево;
  const период = 1 + т.заНизом;
  const список = [];
  for (let и = 0; и < т.сколько; и++) {
    const сырое = порознь(и, т.сколько) * период - (бег || 0);
    const доля = ((сырое % период) + период) % период - т.заНизом;
    const глубь = 1 - доля;
    const близость = Math.pow(глубь, т.законГлубины);
    const y = Math.round(х.горизонт + х.отступГоризонта +
                         (х.высота - х.горизонт - х.отступГоризонта) * близость);
    const в = Math.round(т.высотаДалеко +
                         (т.высотаБлизко - т.высотаДалеко) * близость);
    const сторона = порознь(и + т.сдвигСтороны, т.сколько) < т.поровну ? -1 : 1;
    const даль = т.отДорогиБлиже +
                 порознь(и + т.сдвигДали, т.сколько) * (т.отДорогиДальше - т.отДорогиБлиже);
    const x = Math.round(серединаДороги(y, изгиб) +
                         сторона * (ширинаДороги(y) / 2 + в * даль));
    список.push({ x: x, y: y, в: в, доля: доля, порода: порода(и, т) });
  }
  return список;
}

/*  Где дом стоит на экране. Дальние выше и мельче, ближние ниже и
    крупнее — по тому же закону, что и дорога.                     */
function поставитьДома(список, изгиб) {
  const х = НАСТРОЙКИ.холст, н = х.дом;
  return список.map((д) => {
    const близость = Math.pow(1 - д.доля, н.законРоста);
    const y = Math.round(х.горизонт + н.отступГоризонта +
                         (х.высота - х.горизонт - н.отступНиза) * близость);
    const ш = Math.round(н.ширинаДалеко +
                         (н.ширинаБлизко - н.ширинаДалеко) * близость);
    /*  Вбок дом отходит на столько отступов, сколько насчитала
        карта: пройдёшь мимо — он уедет за край сам, а не пропадёт
        на месте.                                                  */
    const x = Math.round(серединаДороги(y, изгиб) +
                         д.вбок * (ширинаДороги(y) / 2 + ш * н.отступОтДороги));
    return Object.assign({}, д, { x: x, y: y, ш: ш });
  });
}

/* ═══ 5 · ЧТО ВИДНО СНАРУЖИ ════════════════════════════════════════ */

function запуск(узел) {
  холст = узел;
  холст.width = НАСТРОЙКИ.холст.ширина;
  холст.height = НАСТРОЙКИ.холст.высота;
  кисть = холст.getContext('2d');
}

/*  `вид` приходит от карты: { изгиб }. Ничего больше этому файлу
    знать не нужно — он не решает, где герой, он показывает.      */
function рисовать(вид) {
  if (!кисть) return;
  кадр++;
  огни = [];
  const т = время();
  сухость = т.года;
  const п = палитра(т);
  const изгиб = вид ? вид.изгиб : 0;
  небо(п);
  луна(п, 1 - т.суток);
  земля(п);
  дорога(п, изгиб);
  /*  Дальние рисуются первыми, ближние поверх: так ближний дом
      закрывает дальний, а не наоборот.                          */
  /*  Дома и деревья рисуются ОДНИМ ПОРЯДКОМ по глубине: дальнее
      раньше, ближнее поверх. Оттого дерево может закрыть дом, а не
      висеть перед ним или за ним всегда.                        */
  const х = НАСТРОЙКИ.холст;
  const дома = поставитьДома((вид && вид.дома) || [], изгиб);
  последниеДома = дома;
  дома.forEach((д) => тропинка(п, д, изгиб));

  /*  Сухость и её противоположность. Пыль, светляки и ясное небо
      идут от первой, ливень, лужи и густой туман — от второй.    */
  const сухо = Math.max(0, (т.года - х.пыль.отСухости) / (1 - х.пыль.отСухости));
  const дождливость = Math.max(0, (х.дождь.отСухости - т.года) / х.дождь.отСухости);

  const тм = х.туман;
  const плотность = (тм.плотностьНочью + (тм.плотностьДнём - тм.плотностьНочью) * т.суток) *
                    (1 + (х.дождь.туманГуще - 1) * дождливость);
  дымкаЗемли(п, плотность);

  const всё = дома.map((д) => ({ y: д.y, доля: д.доля, что: (пд) => {
      дом(пд, д); столб(пд, д); фонарики(пд, д);
    } }))
    .concat(поставитьДеревья(изгиб, вид && вид.бег)
              .map((д) => ({ y: д.y, доля: д.доля, что: (пд) => дерево(пд, д) })));
  всё.sort((а, б) => а.y - б.y)
     .forEach((что) => что.что(вДымке(п, что.доля, плотность)));

  /*  Лужи кладутся ПОСЛЕ домов и деревьев: они отражают огни, а
      огни к этому мигу уже собраны. И ДО героя: он по лужам идёт,
      а не отражается в них — своё отражение было бы с изломом.

      В сухой сезон их нет: лужа берётся из дождя, а не стоит вечно. */
  лужи(п, изгиб, вид && вид.бег, дождливость);

  /*  Герой рисуется последним: он ближе всего к смотрящему.     */
  герой(п, вид);

  /*  Погода поверх мира, но ДО тьмы: ливень и пыль ночью не светятся
      сами, а светляки светятся — они попадают в огни.            */
  светляки(п, сухо, 1 - т.суток);
  пыль(п, сухо);
  ливень(п, дождливость);

  /*  Тьма ложится поверх всего мира, героя в том числе: ночью он
      такой же тёмный, как улица, и светлеет только у огня.       */
  тьма(1 - т.суток);
  миникарта(п);
}

/*  ТУМАН СЛОЯМИ. Мир выкладывается полосами по глубине, от дальней
    к ближней, и после каждой полосы всё, что дальше неё, заливается
    полупрозрачной дымкой. Дальняя полоса получает заливку шесть раз,
    ближняя ни разу — оттого даль светлеет и теряет цвет, а между
    планами видны полосы, как в образце-07.

    Это главный приём образцов: глубину даёт туман, а не размер.

    Ночью дымка холодная и втрое слабее: ночью даль не светлеет,
    она пропадает.                                                 */
function силаДымки(доля, плотность) {
  const т = НАСТРОЙКИ.холст.туман;
  const д = Math.max(0, Math.min(1, доля));
  return 1 - Math.pow(1 - плотность, т.полос * д);
}

/*  Палитра предмета, отодвинутого вглубь. Каждая краска подмешана к
    туману тем сильнее, чем дальше предмет.

    Красить предмет, а не заливать поверх него, приходится потому, что
    дальний дом торчит ВЫШЕ горизонта: заливка от горизонта вниз
    доставала ему только до пояса. Это я и увидел на первой пробе. */
function вДымке(п, доля, плотность) {
  const сила = силаДымки(доля, плотность);
  if (сила <= 0) return п;
  const из = {};
  for (const имя in п) из[имя] = мешать(п[имя], п.туман, сила);
  return из;
}

/*  ДЫМКА НА ЗЕМЛЕ. Земля и дорога нарисованы до предметов, и им
    хватает заливок поверх: они лежат ниже горизонта целиком.

    Полосы режутся по экрану, а не по глубине: по глубине закон роста
    загоняет дальнюю половину мира в пятнадцать строк, и вся дымка
    собиралась бы там в одну белую нитку.                          */
function дымкаЗемли(п, плотность) {
  const х = НАСТРОЙКИ.холст, т = х.туман;
  const шаг = (х.высота - х.горизонт) / т.полос;
  for (let полоса = 1; полоса < т.полос; полоса++) {
    const край = Math.round(х.горизонт + шаг * полоса);
    кисть.globalAlpha = плотность;
    точки(0, х.горизонт, х.ширина, край - х.горизонт, цвет(п.туман));
    кисть.globalAlpha = 1;
  }
}

/*  ТЬМА С ДЫРАМИ ОТ ОГНЕЙ — второй главный приём образцов.

    В образце-01 нет общего освещения: есть чернота и пятна от огней.
    Делаем так же. Мир рисуется как днём, а поверх кладётся слой тьмы,
    в котором каждый огонь протирает себе круг. Круги, налезая друг на
    друга, протирают сильнее — это и есть сумма вкладов ближних огней.

    Считается на отдельном холсте: протирать надо ИЗ тьмы, а на общем
    холсте под ней лежит уже нарисованный мир, и стирали бы его.   */
function тьма(темнота) {
  const х = НАСТРОЙКИ.холст, т = х.тьма;
  const сила = темнота * т.сила;
  if (сила <= 0) return;
  if (!тень) {
    тень = document.createElement('canvas');
    тень.width = х.ширина; тень.height = х.высота;
    кистьТени = тень.getContext('2d');
  }
  кистьТени.globalCompositeOperation = 'source-over';
  кистьТени.clearRect(0, 0, х.ширина, х.высота);
  кистьТени.fillStyle = цвет(т.краска);
  кистьТени.fillRect(0, 0, х.ширина, х.высота);

  кистьТени.globalCompositeOperation = 'destination-out';
  for (const о of огни) {
    const г = кистьТени.createRadialGradient(о.x, о.y, 0, о.x, о.y, о.р);
    г.addColorStop(0, 'rgba(0,0,0,' + о.сила + ')');
    г.addColorStop(1, 'rgba(0,0,0,0)');
    кистьТени.fillStyle = г;
    кистьТени.fillRect(о.x - о.р, о.y - о.р, о.р * 2, о.р * 2);
  }
  кистьТени.globalCompositeOperation = 'source-over';

  кисть.globalAlpha = сила;
  кисть.drawImage(тень, 0, 0);
  кисть.globalAlpha = 1;
}

/* ═══ 6а · ПОГОДА ══════════════════════════════════════════════════
   Зима отменена. Сезона два, и каждый виден с первого взгляда:
   в дождливый идёт ливень и стоит туман, в сухой висит пыль, а ночью
   летают светляки.

   Всё это — движущиеся точки, считаемые от номера кадра, а не
   хранимые списком: тысяча объектов на кадр нам не нужна, нужен
   вид.                                                            */

/*  ЛИВЕНЬ. Косые штрихи через весь кадр. Идут за верхний край и
    ниже нижнего: обрывать их по краям — значит показать, что дождь
    нарисован, а не идёт.                                          */
function ливень(п, дождливость) {
  const х = НАСТРОЙКИ.холст, д = х.дождь;
  if (дождливость <= 0) return;
  кисть.strokeStyle = цвет(д.краска);
  кисть.lineWidth = д.толщина;
  const высотаХода = х.высота + д.длина + д.длинаРазбег;
  for (let и = 0; и < д.штрихов; и++) {
    const свой = порознь(и, д.штрихов);
    const длина = д.длина + порознь(и + д.штрихов, д.штрихов) * д.длинаРазбег;
    const y = ((свой * высотаХода + кадр * д.скорость / х.времяКадров) % высотаХода);
    const x = порознь(и + д.штрихов * 2, д.штрихов) * (х.ширина + х.высота * д.наклон) -
              х.высота * д.наклон;
    кисть.globalAlpha = (д.сила + свой * д.силаРазбег) * дождливость;
    кисть.beginPath();
    кисть.moveTo(x + y * д.наклон, y - длина);
    кисть.lineTo(x + y * д.наклон + длина * д.наклон, y);
    кисть.stroke();
  }
  кисть.globalAlpha = 1;
}

/*  ПЫЛЬ. В сухой сезон воздух стоит, и в нём висит взвесь. Плывёт
    поперёк медленно и покачивается: падать ей некуда.             */
function пыль(п, сухо) {
  const х = НАСТРОЙКИ.холст, т = х.пыль;
  if (сухо <= 0) return;
  for (let и = 0; и < т.пылинок; и++) {
    const свой = порознь(и, т.пылинок);
    const x = (свой * х.ширина + кадр * т.скорость / х.времяКадров) % х.ширина;
    const y = х.горизонт + порознь(и + т.пылинок, т.пылинок) * (х.высота - х.горизонт) +
              Math.sin(кадр / т.качание + и) * т.качаниеРазмах;
    кисть.globalAlpha = (т.сила + свой * т.силаРазбег) * сухо;
    точки(x, y, т.размер, т.размер, цвет(т.краска));
  }
  кисть.globalAlpha = 1;
}

/*  СВЕТЛЯКИ. Только в сухой сезон и только ночью. Каждый мигает по
    своему счёту и светит сам — оттого они и попадают в огни, по
    которым протирается тьма.                                      */
function светляки(п, сухо, темнота) {
  const х = НАСТРОЙКИ.холст, с = х.светляки;
  const сила = сухо * темнота;
  if (сила <= 0) return;
  for (let и = 0; и < с.сколько; и++) {
    const свой = порознь(и, с.сколько);
    const x = (свой * х.ширина + кадр * с.скорость / х.времяКадров) % х.ширина;
    const y = х.горизонт + с.отГоризонта +
              порознь(и + с.сколько, с.сколько) * (х.высота - х.горизонт - с.отГоризонта) +
              Math.sin(кадр / с.качание + и) * с.качаниеРазмах;
    const мигание = (Math.sin(кадр / с.мерцаниеШаг + и * с.сколько) + 1) / 2;
    кисть.globalAlpha = с.сила * сила * мигание;
    точки(x, y, с.размер, с.размер, цвет(с.краска));
    кисть.globalAlpha = 1;
    огонь(x, y, с.светРадиус, с.светСила * сила * мигание);
  }
}

/*  ЛУЖИ НА ТРОПЕ — приём 3 образцов: отражения там, где мокро.

    В образце-01 дорога не зеркало. Это бурая земля, на которой стоят
    отдельные лужи, и в каждой стоймя отражается ближний огонь.
    Прежде у нас зеркалила вся дорога — вид из черновика, не из
    образца; снял.

    Отражать нечего искать: огни этого кадра уже собраны — те же, по
    которым ночью протирается тьма. Лужа берёт ближние и ставит их
    столбами света вниз.                                           */

function эллипс(цx, цy, ш, в, краска, прозрачность) {
  кисть.globalAlpha = прозрачность;
  кисть.fillStyle = цвет(краска);
  for (let dy = -в; dy <= в; dy++) {
    const доля = 1 - (dy * dy) / (в * в);
    if (доля <= 0) continue;
    const пш = Math.round(ш * Math.sqrt(доля));
    if (пш > 0) кисть.fillRect(Math.round(цx - пш), Math.round(цy + dy), пш * 2, 1);
  }
  кисть.globalAlpha = 1;
}

function лужи(п, изгиб, бег, дождливость) {
  const х = НАСТРОЙКИ.холст, л = х.лужа;
  const мокрость = л.мокрость * (л.сухиеОстатки +
                                 (1 - л.сухиеОстатки) * (дождливость || 0));
  if (мокрость <= 0) return;
  const период = 1 + л.заНизом;
  const наземные = огни.filter((о) => о.y > х.горизонт);

  for (let и = 0; и < л.сколько; и++) {
    /*  Лужи раскладываются ВРОВЕНЬ по глубине, с малой дрожью.
        Наугад они сбивались в кучу у нижнего края и налезали друг
        на друга стопкой — выходили не лужи, а плоские камни.    */
    const сырое = (и / л.сколько) * период +
                  порознь(и, л.сколько) * л.дрожьГлубины - (бег || 0);
    const доля = ((сырое % период) + период) % период - л.заНизом;
    if (доля > 1) continue;
    const y = Math.round(строкаПоДоле(доля));
    if (y < х.горизонт + х.отступГоризонта || y >= х.высота) continue;

    const шд = ширинаДороги(y);
    const вбок = порознь(и + л.сдвигБока, л.сколько) * 2 - 1;   // в обе стороны от середины
    const цx = Math.round(серединаДороги(y, изгиб) + вбок * шд * л.разброс);
    const пш = Math.round(шд * (л.шириной +
                 порознь(и + л.сдвигРазмера, л.сколько) * л.разбегШирины));
    if (пш < л.мельче) continue;
    const пв = Math.max(1, Math.round(пш * л.сплюснутость));

    /*  Сколько огня досталось этой луже. Мокрая земля у фонаря
        отсвечивает вся, а не только под самым огнём.            */
    let тепло = 0;
    for (const о of наземные) {
      const далеко = Math.hypot(о.x - цx, о.y - y);
      if (далеко < л.тёплоРадиус) тепло += о.сила * (1 - далеко / л.тёплоРадиус);
    }
    тепло = Math.min(1, тепло) * л.тёплоСила;

    /*  Гладь. Лужа отражает небо, оттого ночью она синяя, а на
        закате лиловая: цвет глуби подмешан к небу, а не задан.
        Рядом с огнём синева уходит в рыжину.                    */
    /*  тёмная кайма: без неё тёплая лужа сливается с землёй    */
    эллипс(цx, y, пш + 1, пв + 1, л.вода, л.гладь * мокрость * л.кайма);
    эллипс(цx, y, пш, пв,
           мешать(мешать(п.небоНиз, л.вода, л.небаВЛуже), п.теплоС, тепло),
           л.гладь * мокрость);
    /* светлая кромка у дальнего края — там, где вода тоньше */
    эллипс(цx, y - пв + 1, пш, Math.max(1, Math.round(пв * л.кромка)),
           п.зарево, л.гладь * мокрость * л.кромка * 2);

    /*  Огонь в луже: столб света вниз, с дрожью по строкам.      */
    for (const о of наземные) {
      const мимо = Math.abs(о.x - цx);
      if (мимо > пш + л.бликШирина) continue;
      const дальше = Math.abs(о.y - y);
      if (дальше > л.бликДалеко) continue;
      const сила = л.бликСила * о.сила * мокрость *
                   (1 - дальше / л.бликДалеко) * (1 - мимо / (пш + л.бликШирина));
      кисть.fillStyle = цвет(п.теплоС);
      for (let dy = -пв; dy <= пв; dy++) {
        const доляВ = 1 - (dy * dy) / (пв * пв);
        if (доляВ <= 0) continue;
        const дрожь = Math.sin((y + dy) * л.бликДрожь + кадр / л.бликШагДрожи);
        кисть.globalAlpha = сила * доляВ;
        кисть.fillRect(Math.round(о.x + дрожь - л.бликШирина / 2),
                       y + dy, л.бликШирина, 1);
      }
      кисть.globalAlpha = 1;
    }

    /*  Рябь: короткие светлые штрихи поперёк.                    */
    for (let р = 0; р < л.рябьСколько; р++) {
      const dy = Math.round(-пв / 2 + р * пв);
      const сдвиг = Math.sin(кадр / л.бликШагДрожи + и + р) * пш * л.кромка;
      кисть.globalAlpha = л.рябьСила * мокрость;
      точки(цx - пш / 2 + сдвиг, y + dy, пш, 1, цвет(п.зарево));
      кисть.globalAlpha = 1;
    }
  }
}

/* ═══ 7 · МИНИКАРТА ════════════════════════════════════════════════
   Три кольца, восемь лучей, Сердце, ворота и точка героя. Место
   героя настоящее: берётся у карты, а не рисуется наугад.

   По нажатию раскрывается до трети экрана и сворачивается обратно.
   Указатели на перекрёстках остаются как были.                     */

let холстик = null, кистьМини = null;

function миникарта(п) {
  if (!кистьМини) return;
  const м = НАСТРОЙКИ.холст.мини;
  const МИР = window.МИР_ДАННЫЕ;
  const ц = м.сторона / 2;
  const внешний = МИР.кольца[МИР.кольца.length - 1].радиус;
  const мера = (радиус) => радиус / внешний * (ц - м.поле);

  кистьМини.fillStyle = м.краскаФон;
  кистьМини.fillRect(0, 0, м.сторона, м.сторона);

  кистьМини.strokeStyle = м.краскаДорог;
  МИР.кольца.forEach((к, и) => {
    кистьМини.lineWidth = и === 0 ? 2 : 1;
    кистьМини.beginPath();
    кистьМини.arc(ц, ц, мера(к.радиус), 0, Math.PI * 2);
    кистьМини.stroke();
  });

  кистьМини.lineWidth = 1;
  МИР.лучи.forEach((угол) => {
    const р = угол * Math.PI / м.полуоборот;
    кистьМини.beginPath();
    кистьМини.moveTo(ц + Math.cos(р) * мера(МИР.кольца[0].радиус),
                     ц + Math.sin(р) * мера(МИР.кольца[0].радиус));
    кистьМини.lineTo(ц + Math.cos(р) * мера(внешний),
                     ц + Math.sin(р) * мера(внешний));
    кистьМини.stroke();
  });

  /* Сердце в середине */
  кистьМини.fillStyle = цвет(п.тепло);
  кистьМини.beginPath();
  кистьМини.arc(ц, ц, м.сердце, 0, Math.PI * 2);
  кистьМини.fill();

  /* ворота на концах лучей */
  кистьМини.fillStyle = цвет(п.деревоТ);
  НАСТРОЙКИ.карта.стена.ворот.forEach((угол) => {
    const р = угол * Math.PI / м.полуоборот;
    кистьМини.fillRect(ц + Math.cos(р) * (мера(внешний) + м.воротаЗа) - м.ворота / 2,
                       ц + Math.sin(р) * (мера(внешний) + м.воротаЗа) - м.ворота / 2,
                       м.ворота, м.ворота);
  });

  /* точка героя — настоящая, из мира */
  const т = window.КАРТА && window.КАРТА.точкаМира && window.КАРТА.точкаМира();
  if (т) {
    const центрМира = НАСТРОЙКИ.карта.центр;
    кистьМини.fillStyle = м.краскаГероя;
    кистьМини.fillRect(ц + (т.x - центрМира) / внешний * (ц - м.поле) - м.герой / 2,
                       ц + (т.y - центрМира) / внешний * (ц - м.поле) - м.герой / 2,
                       м.герой, м.герой);
  }
}

/* ═══ 8 · ЧТО ВИДНО СНАРУЖИ ════════════════════════════════════════ */

function запуск(узел) {
  холст = узел;
  холст.width = НАСТРОЙКИ.холст.ширина;
  холст.height = НАСТРОЙКИ.холст.высота;
  кисть = холст.getContext('2d');
  кисть.imageSmoothingEnabled = false;

  const м = НАСТРОЙКИ.холст.мини;
  холстик = document.getElementById(м.имяХолстика);
  if (холстик) {
    холстик.width = холстик.height = м.сторона;
    кистьМини = холстик.getContext('2d');
    кистьМини.imageSmoothingEnabled = false;
    const окно = document.getElementById(м.имяОкна);
    if (окно) окно.addEventListener('click', () => окно.classList.toggle(м.имяРаскрытой));
  }
}

/*  Какой дом под пальцем. Ближние проверяются первыми: они
    нарисованы поверх, и попасть надо в тот, что видно.

    Точка приходит в точках экрана, а холст растянут, — поэтому
    сперва переводим её в точки холста.                           */
function домВТочке(экранX, экранY) {
  if (!холст) return null;
  const рамка = холст.getBoundingClientRect();
  if (!рамка.width || !рамка.height) return null;
  const x = (экранX - рамка.left) / рамка.width * НАСТРОЙКИ.холст.ширина;
  const y = (экранY - рамка.top) / рамка.height * НАСТРОЙКИ.холст.высота;

  const по_близости = последниеДома.slice().sort((а, б) => б.y - а.y);
  for (const д of по_близости) {
    const верх = д.верх === undefined ? д.y - д.ш : д.верх;
    if (x >= д.x - д.ш / 2 && x <= д.x + д.ш / 2 && y >= верх && y <= д.y) {
      return д.ключ;
    }
  }
  return null;
}

return { запуск: запуск, рисовать: рисовать, глубина: глубина,
         домВТочке: домВТочке,
         напоказ: (с, г) => { напоказ = с === null ? null : { суток: с, года: г }; },
         ширинаДороги: ширинаДороги, серединаДороги: серединаДороги };
})();
